_FIELDS = {
    "vp_true": (_VP_TRUE_B85, _VP_TRUE_SHAPE),
    "vp_smooth": (_VP_SMOOTH_B85, _VP_SMOOTH_SHAPE),
    "vp_linear": (_VP_LINEAR_B85, _VP_LINEAR_SHAPE),
    "vs_true": (_VS_TRUE_B85, _VS_TRUE_SHAPE),
    "vs_smooth": (_VS_SMOOTH_B85, _VS_SMOOTH_SHAPE),
    "vs_linear": (_VS_LINEAR_B85, _VS_LINEAR_SHAPE),
    "rho_true": (_RHO_TRUE_B85, _RHO_TRUE_SHAPE),
    "rho_smooth": (_RHO_SMOOTH_B85, _RHO_SMOOTH_SHAPE),
    "rho_linear": (_RHO_LINEAR_B85, _RHO_LINEAR_SHAPE),
}


def available() -> list[str]:
    """Return the list of preset velocity-model names embedded in this module."""
    return list(_FIELDS)


def load_marmousi(name: str = "vp_true") -> np.ndarray:
    """Decode and return one of the embedded marmousi velocity models.

    Args:
        name: model preset, one of ``['vp_true', 'vp_smooth', 'vp_linear', 'vs_true', 'vs_smooth', 'vs_linear', 'rho_true', 'rho_smooth', 'rho_linear']``.

    Returns:
        ``np.ndarray`` of dtype ``float32`` with the model on the package grid.
    """
    if name not in _FIELDS:
        raise KeyError(
            f"Unknown marmousi preset {name!r}; available: {available()}"
        )
    blob, shape = _FIELDS[name]
    raw = zlib.decompress(base64.b85decode("".join(blob)))
    return np.frombuffer(raw, dtype=np.float16).reshape(shape).astype(np.float32)
